from mk import *
from lib import fbd
STRICT["on"] = True
PTS = [(0.02, 0.2), (0.04, 0.42), (0.06, 0.66), (0.08, 0.88), (0.10, 1.12), (0.12, 1.3)]
n = 6; xm = sum(p[0] for p in PTS) / n; ym = sum(p[1] for p in PTS) / n
slope = sum((x - xm) * (y - ym) for x, y in PTS) / sum((x - xm) ** 2 for x, _ in PTS)

def fig():
    g = Fig(560, 300, "כדור גדול M תלוי בחוט מנקודה O, מוסט לגובה h ומשוחרר, ופוגע בכדור קטן m בקצה שולחן בגובה H. הכדור הקטן נוחת במרחק d. וגרף d בריבוע כפונקציה של h: קו ישר מ-0.2 ב-0.02 מטר עד 1.3 ב-0.12 מטר")
    g.rect(30, 140, 150, 14, fill="var(--d-fill)"); g.line(180, 140, 180, 270, width=2); g.ground(20, 290, 270)
    g.dot(150, 30); g.text(150, 22, "O"); g.line(150, 30, 150, 126, stroke="var(--d-dim)", width=1, dash="3 3")
    g.line(150, 30, 100, 110, width=1.5); g.ball(100, 116, 10); g.text(84, 104, "M", anchor="end")
    g.ball(172, 133, 6); g.text(186, 128, "m", anchor="start")
    g.dim(60, 116, 60, 133, "h", offset=0)
    g.path("M 178,133 Q 240,140 260,268", stroke="var(--d-dim)", width=1.4, dash="5 4")
    g.dim(180, 255, 260, 255, "d", offset=0); g.dim(200, 154, 200, 270, "H", offset=0)
    X, Y = g.graph(330, 270, 190, 220, "h (m)", "d² (m²)", xticks=[(v / 100, f"{v/100:g}") for v in (4, 8, 12)], yticks=[(v / 10, f"{v/10:g}") for v in (2, 4, 6, 8, 10, 12, 14)], xmax=0.15, ymax=1.5)
    for x, y in PTS: g.dot(X(x), Y(y))
    g.plot(X, Y, [(0, 0), (0.125, 0.125 * slope)], width=1.6)
    return g

E(id="bagrut-2002-q3", year=2002, label="2002 שאלה 3", topic="momentum", sub="mom-collisions", diff=4, fig=fig,
  stem=r"התרשים מראה ניסוי של תלמיד. כדור קטן שמסתו $m$ מונח על קצה שולחן. כדור גדול שמסתו $M$ קשור בחוט קל לנקודה קבועה $O$. כשהחוט אנכי, הכדורים נוגעים זה בזה, והמרכזים שלהם באותו גובה $H$ מעל הרצפה. התלמיד מרים את הכדור הגדול כך שמרכזו גבוה ב-$h$ ממרכז הכדור הקטן, ומשחרר אותו ממנוחה. הכדור הגדול פוגע חזיתית בכדור הקטן, והכדור הקטן עף ונוחת על הרצפה במרחק אופקי $d$ מקצה השולחן. רגע לפני ההתנגשות מהירות הכדור הגדול $v$, ורגע אחריה $\tfrac{3}{4}v$, באותו כיוון. מזניחים את התנגדות האוויר.",
  parts=[
    P("א", r"מה גודל המהירות $u$ של הכדור הקטן רגע אחרי ההתנגשות, בעזרת $h$, $M$, $m$ ו-$g$?", choice([r"$u = \frac{M\sqrt{2gh}}{4m}$", r"$u = \frac{3M\sqrt{2gh}}{4m}$", r"$u = \frac{M\sqrt{gh}}{4m}$", r"$u = \frac{m\sqrt{2gh}}{4M}$"], 0), ["principle", "algebra"], [
        X(r"הכיוון החיובי הוא כיוון התנועה של הכדור הגדול לפני ההתנגשות."),
        S(r"מהירות הכדור הגדול לפני ההתנגשות", r"שימור אנרגיה: המתיחות ניצבת לתנועה ולא עושה עבודה. המסה מצטמצמת", r"Mgh = \tfrac{1}{2}Mv^2 \;\Rightarrow\; v = \sqrt{2gh}", eq=r"E_k = \tfrac{1}{2}mv^2,\quad U_G = mgh"),
        S(r"שימור תנע בהתנגשות", r"הכדור הקטן היה במנוחה", r"Mv + 0 = M \cdot \tfrac{3}{4}v + m u", eq=r"m_A\vec v_A + m_B\vec v_B = m_A\vec u_A + m_B\vec u_B"),
        S(r"מבודדים", r"מציבים את מהירות הכדור הגדול", r"u = \frac{M v}{4m} = \frac{M\sqrt{2gh}}{4m}"),
    ], r"$u = \frac{M\sqrt{2gh}}{4m}$", key=r"u = M√(2gh)/(4m)"),
    P("ב", r"הוכיחו ש-$d^2 = \frac{H M^2}{4m^2}h$.", OPEN, ["principle", "algebra"], [
        X(r"בציר האנכי בוחרים כלפי מטה כחיובי."),
        S(r"זמן הנפילה", r"הכדור הקטן עף אופקית, ולכן בציר האנכי הוא יוצא בלי מהירות", r"H = \tfrac{1}{2}g t^2 \;\Rightarrow\; t^2 = \frac{2H}{g}", eq=r"x = x_0 + v_0 t + \tfrac{1}{2}at^2"),
        S(r"המרחק האופקי", r"בציר האופקי המהירות קבועה. מעלים בריבוע ומציבים את המהירות מהסעיף הקודם", r"d^2 = u^2 t^2 = \frac{M^2 \cdot 2gh}{16m^2} \cdot \frac{2H}{g} = \frac{H M^2}{4m^2}\,h"),
    ], r"$d^2 = u^2 t^2 = \frac{HM^2}{4m^2}h$"),
    P("ג", r"התלמיד חזר על הניסוי כמה פעמים, ובכל פעם שינה את $h$ ומדד את $d$. נתון: $M = 140\,\text{g}$, $m = 20\,\text{g}$, $H = 90\,\text{cm}$. מהמדידות הוא שרטט גרף של $d^2$ כפונקציה של $h$. מה השיפוע של הגרף? הראו שהתוצאות מתאימות לקשר מסעיף ב.", num(slope, "m", tol=5), ["graph", "algebra"], [
        S(r"השיפוע מהגרף", r"בוחרים שתי נקודות רחוקות זו מזו על הקו", r"\frac{1.3 - 0.2}{0.12 - 0.02} = 11\,\text{m}"),
        S(r"השיפוע הצפוי", r"לפי הקשר מהסעיף הקודם, השיפוע הוא כל מה שמכפיל את הגובה", r"\frac{HM^2}{4m^2} = \frac{0.9 \cdot 140^2}{4 \cdot 20^2} = \frac{0.9 \cdot 49}{4} \approx 11.0\,\text{m}"),
        S(r"צורת הגרף", r"הקשר הוא יחס ישר, ולכן הגרף צריך להיות קו ישר שעובר בראשית, וכך הוא", r"d^2 \propto h"),
    ], r"$\approx 11\,\text{m}$, כמו בחישוב, והגרף קו ישר דרך הראשית"),
  ],
  concepts=["שימור אנרגיה", "שימור תנע בהתנגשות", "זריקה אופקית", "לינאריזציה"],
  summary=r"כדור תלוי שמכה כדור קטן על קצה שולחן: המהירות אחרי ההתנגשות, הקשר בין ריבוע המרחק לגובה, והשוואה לגרף הניסוי.",
  review="הנחה שלי.\nבסעיף א התלמיד בוחר את הביטוי הנכון מתוך ארבעה.\nמה לבדוק: רק לאשר.")
